sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        var r = new sn_ws.RESTMessageV2('External Identity Provider API', 'Provision Access');
        
        r.setStringParameterNoEscape('user_id', inputs.user_id);
        r.setStringParameterNoEscape('target_app', inputs.target_app);
        
        var response = r.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();
        
        gs.info("IdP Provisioning Status: " + httpStatus + " | Body: " + responseBody);
    } catch (ex) {
        gs.error("IdP Provisioning Failed: " + ex.message);
    }
})(inputs, outputs);

